# ec_hr_attendance_appeal — HR MVP U1-hardened (2026-07-20). POST. Tao native Attendance Request (draft).
# U1: KHONG tao request neu khong resolve duoc Direct Manager (reports_to -> user enabled + System User).
# Khong fallback HR, khong fake manager. Idempotent.
u = frappe.session.user
if u == 'Guest':
    frappe.throw('Khong duoc phep')
emp = frappe.db.get_value('Employee', {'user_id': u, 'status': 'Active'}, ['name', 'default_shift', 'holiday_list', 'company', 'reports_to'], as_dict=True)
if not emp:
    frappe.throw('Khong tim thay ho so nhan vien cho tai khoan nay.')
mgr_user = None
if emp.reports_to:
    cand = frappe.db.get_value('Employee', emp.reports_to, 'user_id')
    if cand:
        row = frappe.db.get_value('User', cand, ['enabled', 'user_type'], as_dict=True)
        if row and row.enabled and row.user_type == 'System User':
            mgr_user = cand
if not mgr_user:
    frappe.throw('Khong xac dinh duoc Quan ly truc tiep cua ban nen chua the gui giai trinh. Vui long lien he CnB/HR de cap nhat \'Bao cao cho\' (reports_to) trong ho so nhan su.')
d = frappe.form_dict.get('date')
note = frappe.form_dict.get('explanation') or ''
if not d or len(d) != 10:
    frappe.throw('Thieu ngay (YYYY-MM-DD)')
today = frappe.utils.nowdate()
if d > today:
    frappe.throw('Khong appeal ngay tuong lai')
# MP-1 lock guard: khong tao appeal moi neu ky da Locked hoac qua appeal_deadline.
pm = d[0:7]
prow = frappe.db.sql("select status, appeal_deadline from `tabEC HR Monthly Period` where period_month=%s", (pm,))
if not prow:
    # 'no period' = transitional; fail-closed khi enforce_period_required=1 (monthly auto-gen active).
    enforce = frappe.db.get_single_value('EC Performance Settings', 'enforce_period_required')
    if enforce:
        frappe.throw('Ky ' + pm + ' chua duoc mo (Monthly Period). Lien he CnB/HR.')
if prow:
    if prow[0][0] == 'Locked':
        frappe.throw('Ky ' + pm + ' da bi khoa (Monthly HR Lock). Lien he CnB/HR neu can mo lai.')
    dl = prow[0][1]
    if dl and frappe.utils.now_datetime() > frappe.utils.get_datetime(dl):
        frappe.throw('Da qua han giai trinh cham cong cua ky ' + pm + ' (deadline ' + str(dl) + ').')
hl = emp.holiday_list
if not hl:
    hl = frappe.db.get_value('Company', emp.company, 'default_holiday_list')
if hl:
    hrow = frappe.db.sql('select 1 from `tabHoliday` where parent=%s and holiday_date=%s', (hl, d))
    if hrow:
        frappe.throw('Ngay nghi le/cuoi tuan - khong can appeal')
att = frappe.db.sql('select status from `tabAttendance` where employee=%s and attendance_date=%s and docstatus<2', (emp.name, d))
if att:
    frappe.throw('Ngay nay da co cham cong: ' + str(att[0][0]))
ex = frappe.db.sql("select name from `tabAttendance Request` where employee=%s and from_date<=%s and to_date>=%s and docstatus=0 and ifnull(ec_appeal_status,'Open')='Open'", (emp.name, d, d))
if ex:
    frappe.response['message'] = {'status': 'already', 'name': ex[0][0]}
else:
    ar = frappe.get_doc({'doctype': 'Attendance Request', 'employee': emp.name, 'from_date': d, 'to_date': d, 'reason': 'On Duty', 'explanation': note, 'shift': emp.default_shift, 'company': emp.company, 'ec_appeal_status': 'Open'})
    ar.insert(ignore_permissions=True)
    td = frappe.get_doc({'doctype': 'ToDo', 'allocated_to': mgr_user, 'reference_type': 'Attendance Request', 'reference_name': ar.name, 'description': 'Duyet appeal cham cong ngay ' + d + ' cua ' + emp.name, 'priority': 'Medium', 'status': 'Open'})
    td.insert(ignore_permissions=True)
    frappe.response['message'] = {'status': 'created', 'name': ar.name, 'assigned_to': mgr_user}

# ec_hr_checkin_reminder - nhac cham cong 8h30 cho nguoi CHUA cham hom nay.
# Chay Cron moi gio phut 30; chi thuc thi khi GIO DIA PHUONG = 8 (tranh lech timezone cua server).
now = frappe.utils.now_datetime()
if now.hour == 8:
    today = frappe.utils.nowdate()
    rows = frappe.db.sql("select name, employee_name, user_id, holiday_list from `tabEmployee` where status='Active' and ifnull(user_id,'')<>''")
    sent = 0
    for r in rows:
        emp = r[0]
        usr = r[2]
        hl = r[3]
        skip = 0
        if hl:
            hd = frappe.db.sql('select name from `tabHoliday` where parent=%s and holiday_date=%s limit 1', (hl, today))
            if hd:
                skip = 1
        if not skip:
            lv = frappe.db.sql("select name from `tabLeave Application` where employee=%s and docstatus=1 and status='Approved' and from_date<=%s and to_date>=%s limit 1", (emp, today, today))
            if lv:
                skip = 1
        if not skip:
            ci = frappe.db.sql('select name from `tabEmployee Checkin` where employee=%s and date(time)=%s limit 1', (emp, today))
            if ci:
                skip = 1
        if not skip:
            dup = frappe.db.sql("select name from `tabNotification Log` where for_user=%s and document_name=%s and date(creation)=%s and subject like '%%cham cong%%' limit 1", (usr, emp, today))
            if dup:
                skip = 1
        if not skip:
            doc = frappe.get_doc({'doctype': 'Notification Log', 'for_user': usr, 'type': 'Alert', 'document_type': 'Employee', 'document_name': emp, 'subject': 'Nhac cham cong hom nay', 'email_content': '<p>Ban chua cham cong hom nay. Mo app eCentric ERP de cham cong truoc 10:00.</p>', 'link': '/ec-hr/attendance'})
            doc.flags.ignore_permissions = True
            doc.insert(ignore_permissions=True)
            sent = sent + 1
    frappe.log_error('ec_hr_checkin_reminder sent=' + str(sent) + ' date=' + str(today), 'ec_hr_checkin_reminder')

