# ec_hr_late_early_preview - cho form xem truoc se bi tru bao nhieu phep.
# Thuan tinh toan, khong ghi gi. Day cung la cho KIEM CHUNG bang bac.
ct = frappe.form_dict.get('check_time')
cto = frappe.form_dict.get('check_time_other')
rt = frappe.form_dict.get('request_type')
# --- BANG BAC TRU PHEP -----------------------------------------------------
# Ca chuan EC Standard 9-18. Chinh sach cong ty 2026-08-21:
#   duoi 2h -> 0.25 ngay | 2h den 4h -> 0.5 | tren 4h den 6h -> 0.75 | tren 6h -> 1
#
# Viet PHANG (khong dung def) la CO Y: sandbox cua DocType Event khong cho ham
# nhin thay bien toan cuc cua chinh script -- dat trong def se NameError luc chay.
#
# Doan nay lap lai y het trong ec_hr_late_early_preview (Server Script khong
# import duoc nhau). SUA MOT BEN THI SUA CA HAI.
SHIFT_START = 9.0
SHIFT_END = 18.0
LATE = '\u0110i tr\u1ec5'
EARLY = 'V\u1ec1 s\u1edbm'
HOURS = {'10 AM':10.0,'11 AM':11.0,'12 PM':12.0,'1 PM':13.0,'2 PM':14.0,'3 PM':15.0,'4 PM':16.0,'5 PM':17.0}

h = None
t = (ct or '').strip()
if t != 'Other':
    h = HOURS.get(t)
else:
    raw = (cto or '').strip()
    low = raw.lower()
    nums = []
    cur = ''
    for ch in raw:
        if ch.isdigit():
            cur = cur + ch
        else:
            if cur:
                nums.append(cur)
            cur = ''
    if cur:
        nums.append(cur)
    if nums:
        hh = int(nums[0][:2])
        mm = int(nums[1][:2]) if len(nums) > 1 else 0
        if mm > 59:
            mm = 0
        if 'pm' in low and hh < 12:
            hh = hh + 12
        if 'am' in low and hh == 12:
            hh = 0
        if hh <= 23:
            h = hh + (mm / 60.0)

hrs = None
pen = 0.0
if h is not None:
    rts = (rt or '').strip()
    if rts == EARLY:
        hrs = SHIFT_END - h
    elif rts == LATE:
        hrs = h - SHIFT_START
    else:
        # ban ghi cu chua co request_type: doan theo gio, truoc 13h coi la di tre
        hrs = (h - SHIFT_START) if h < 13 else (SHIFT_END - h)
    hrs = round(hrs, 2)
    if hrs <= 0:
        pen = 0.0
    elif hrs < 2:
        pen = 0.25
    elif hrs <= 4:
        pen = 0.5
    elif hrs <= 6:
        pen = 0.75
    else:
        pen = 1.0
if h is None:
    frappe.response['message'] = {'ok': False, 'reason': 'khong doc duoc gio'}
else:
    frappe.response['message'] = {'ok': True, 'hours': hrs, 'penalty': pen}

