# ec_hr_leave_one - HR MVP. POST. Chi tiet 1 don nghi phep cho popup + kiem quyen xem.
u = frappe.session.user
if u == 'Guest':
    frappe.throw('Khong duoc phep')
nm = frappe.form_dict.get('name')
if not nm:
    frappe.throw('Thieu tham so')
rows = frappe.db.sql("select name, employee, employee_name, leave_type, from_date, to_date, total_leave_days, ifnull(half_day,0), status, ifnull(ec_approval_stage,''), ifnull(description,''), owner, creation, modified, modified_by, leave_approver, posting_date from `tabLeave Application` where name=%s limit 1", (nm,))
if not rows:
    frappe.throw('Khong tim thay don')
r = rows[0]
emp_id = r[1]
me = frappe.db.get_value('Employee', {'user_id': u, 'status': 'Active'}, ['name', 'lft', 'rgt'], as_dict=True)
is_hr = frappe.db.sql("select 1 from `tabHas Role` where parent=%s and role in ('HR Manager','HR User') limit 1", (u,))
allowed = bool(is_hr) or (u == 'Administrator')
if not allowed and me:
    if emp_id == me.name:
        allowed = True
    elif me.lft is not None:
        sub = frappe.db.sql("select 1 from `tabEmployee` where name=%s and lft > %s and rgt < %s limit 1", (emp_id, me.lft, me.rgt))
        if sub:
            allowed = True
if not allowed:
    frappe.throw('Ban khong co quyen xem don nay')
decided = r[8] in ('Approved', 'Rejected')
sub_by = frappe.db.get_value('User', r[11], 'full_name') or r[11]
dec_by = frappe.db.get_value('User', r[14], 'full_name') or r[14]
