# ec_hr_perf — MP-2 (2026-07-21). POST dispatcher: generate|get|employee_submit|manager_review.
# Workload nhap dang JSON -> parse thanh CHILD ROWS (khong luu JSON blob). SLA/bonus = MP-3/MP-4.
u = frappe.session.user
action = frappe.form_dict.get('action')

def roles_of(usr):
    rr = frappe.db.sql('select role from `tabHas Role` where parent=%s and parenttype=%s', (usr, 'User'))
    acc = []
    for x in rr:
        acc = acc + [x[0]]
    return acc

my_roles = roles_of(u)
is_all = 'EC CnB Payroll' in my_roles or 'EC CnB' in my_roles or 'EC HR Period Admin' in my_roles
my_emp = frappe.db.get_value('Employee', {'user_id': u, 'status': 'Active'}, 'name')

if action == 'brands':
    rows = frappe.db.sql("select name, ifnull(ec_legacy_key,'') from `tabBrand` order by name")
    bl = []
    for b in rows:
        bl = bl + [{'name': b[0], 'legacy': b[1]}]
    frappe.response['message'] = {'brands': bl}

elif action == 'generate':
    if not (is_all or 'EC HR Period Admin' in my_roles or u == 'Administrator'):
        frappe.throw('Chi CnB/HR/Period Admin duoc generate.')
    pm = frappe.form_dict.get('period_month')
    if not frappe.db.exists('EC HR Monthly Period', pm):
        frappe.throw('Ky chua ton tai.')
    emps = frappe.db.sql("select name from `tabEmployee` where status='Active' and ifnull(user_id,'')!=''")
    made = 0
    for e in emps:
        if not frappe.db.exists('EC Monthly Performance', {'period': pm, 'employee': e[0]}):
            d = frappe.get_doc({'doctype': 'EC Monthly Performance', 'employee': e[0], 'period': pm, 'workflow_state': 'Draft'})
            d.insert(ignore_permissions=True)
            made = made + 1
    frappe.response['message'] = {'generated': made, 'period': pm}

elif action == 'get':
    pm = frappe.form_dict.get('period_month')
    if is_all:
        rows = frappe.db.sql("select name, employee, employee_name, workflow_state, rating, workload_total_pct from `tabEC Monthly Performance` where period=%s order by employee_name", (pm,))
    elif my_emp:
        subs = frappe.db.sql('select name from `tabEmployee` where reports_to=%s', (my_emp,))
        ids = [my_emp]
        for sname in subs:
            ids = ids + [sname[0]]
        ph = ','.join(['%s'] * len(ids))
        rows = frappe.db.sql("select name, employee, employee_name, workflow_state, rating, workload_total_pct from `tabEC Monthly Performance` where period=%s and employee in (" + ph + ") order by employee_name", tuple([pm] + ids))
    else:
        frappe.throw('Khong tim thay ho so nhan vien.')
    out = []
    for r in rows:
        wl = frappe.db.sql("select brand, employee_pct, manager_pct, revised, revise_reason from `tabEC Performance Workload` where parent=%s order by idx", (r[0],))
        wlist = []
        for w in wl:
            wlist = wlist + [{'brand': w[0], 'employee_pct': w[1], 'manager_pct': w[2], 'revised': w[3], 'revise_reason': w[4]}]
        out = out + [{'name': r[0], 'employee': r[1], 'employee_name': r[2], 'status': r[3], 'rating': r[4], 'total_pct': r[5], 'workload': wlist, 'is_own': (r[1] == my_emp), 'can_review': (frappe.db.get_value('Employee', r[1], 'reports_to') == my_emp) or is_all}]
    brows = frappe.db.sql('select name from `tabBrand` order by name')
    blist = []
    for b in brows:
        blist = blist + [b[0]]
    frappe.response['message'] = {'period': pm, 'records': out, 'is_all': 1 if is_all else 0, 'is_cnb': 1 if is_all else 0, 'brands': blist, 'my_emp': my_emp}

elif action == 'employee_submit':
    name = frappe.form_dict.get('name')
    doc = frappe.get_doc('EC Monthly Performance', name)
    if doc.employee != my_emp and u != 'Administrator':
        frappe.throw('Chi duoc gui ho so cua chinh minh.')
    if doc.workflow_state not in ('Draft',):
        frappe.throw('Chi gui khi trang thai Draft.')
    raw = frappe.form_dict.get('workload') or '[]'
    items = json.loads(raw)
    total = 0.0
    rows = []
    for it in items:
        pct = float(it.get('employee_pct') or 0)
        total = total + pct
        rows = rows + [{'brand': it.get('brand'), 'employee_pct': pct, 'manager_pct': pct, 'revised': 0}]
    if abs(total - 100.0) > 0.01:
        frappe.throw('Tong ty le phai = 100%% (hien tai ' + str(total) + ').')
    doc.set('workload', rows)
    doc.workload_total_pct = total
    doc.workflow_state = 'Submitted'
    doc.submitted_at = frappe.utils.now_datetime()
    doc.flags.ignore_permissions = True
    doc.save(ignore_permissions=True)
    frappe.response['message'] = {'status': 'submitted', 'name': name, 'total': total}

elif action == 'manager_review':
    name = frappe.form_dict.get('name')
    doc = frappe.get_doc('EC Monthly Performance', name)
    mgr = frappe.db.get_value('Employee', doc.employee, 'reports_to')
    if not (mgr == my_emp or is_all or u == 'Administrator'):
        frappe.throw('Chi Quan ly truc tiep hoac CnB/HR duoc review.')
    if doc.workflow_state != 'Submitted':
        frappe.throw('Chi review khi trang thai Submitted.')
    raw = frappe.form_dict.get('workload') or '[]'
    items = json.loads(raw)
    bybrand = {}
    for it in items:
        bybrand[it.get('brand')] = it
    total = 0.0
    for row in doc.workload:
        it = bybrand.get(row.brand)
        if it is not None:
            newp = float(it.get('manager_pct') or 0)
            if abs(newp - float(row.employee_pct or 0)) > 0.01:
                row.revised = 1
                row.revise_reason = it.get('revise_reason') or row.revise_reason
            row.manager_pct = newp
        total = total + float(row.manager_pct or 0)
    if abs(total - 100.0) > 0.01:
        frappe.throw('Tong ty le (manager) phai = 100%% (hien tai ' + str(total) + ').')
    rating = frappe.form_dict.get('rating')
    if rating in ('A', 'B', 'C'):
        doc.rating = rating
    doc.workload_total_pct = total
    doc.workflow_state = 'Manager Reviewed'
    doc.reviewed_at = frappe.utils.now_datetime()
    doc.reviewed_by = u
    doc.flags.ignore_permissions = True
    doc.save(ignore_permissions=True)
    frappe.response['message'] = {'status': 'manager_reviewed', 'name': name, 'rating': doc.rating, 'total': total}

else:
    frappe.throw('action khong hop le')

# ec_hr_period_manage — MP-1 (2026-07-21). POST. CnB/HR/SM only.
# actions: create_or_open (idempotent), lock, reopen. Dates auto tu EC Performance Settings.
# Audit qua track_changes (Version) tren EC HR Monthly Period. Auto-gen Monthly Performance = MP-2.
u = frappe.session.user
is_priv = frappe.db.sql("select 1 from `tabHas Role` where parent=%s and role in ('EC HR Period Admin','EC CnB Payroll','EC CnB')", (u,))
if not is_priv and u != 'Administrator':
    frappe.throw('Chi role duoc quan tri (EC HR Period Admin / EC CnB Payroll) duoc quan ly ky.')
action = frappe.form_dict.get('action')
ym = frappe.form_dict.get('period_month')
if not ym or len(ym) != 7 or ym[4:5] != '-':
    frappe.throw('period_month sai dinh dang (YYYY-MM)')
adl_v = frappe.db.get_single_value('EC Performance Settings', 'appeal_deadline_day')
lkd_v = frappe.db.get_single_value('EC Performance Settings', 'lock_day')
adl = int(adl_v or 2)
lkd = int(lkd_v or 3)
first = ym + '-01'
start_date = str(frappe.utils.get_first_day(first))
end_date = str(frappe.utils.get_last_day(first))
next_first = frappe.utils.add_months(first, 1)
appeal_deadline = str(frappe.utils.add_days(next_first, adl - 1)) + ' 23:59:59'
lock_date = str(frappe.utils.add_days(next_first, lkd - 1)) + ' 00:00:00'
exists = frappe.db.exists('EC HR Monthly Period', ym)
if action == 'create_or_open':
    if exists:
        doc = frappe.get_doc('EC HR Monthly Period', ym)
        changed = False
        if doc.status == 'Locked':
            frappe.throw('Ky dang Locked; dung action=reopen (co ly do) de mo lai.')
        frappe.response['message'] = {'status': 'exists', 'name': ym, 'period_status': doc.status}
    else:
        doc = frappe.get_doc({'doctype': 'EC HR Monthly Period', 'period_month': ym, 'start_date': start_date, 'end_date': end_date, 'appeal_deadline': appeal_deadline, 'lock_date': lock_date, 'status': 'Open'})
        doc.insert(ignore_permissions=True)
        frappe.response['message'] = {'status': 'created', 'name': ym, 'start_date': start_date, 'end_date': end_date, 'appeal_deadline': appeal_deadline, 'lock_date': lock_date}
elif action == 'lock':
    if not exists:
        frappe.throw('Ky chua ton tai; tao truoc (create_or_open).')
    doc = frappe.get_doc('EC HR Monthly Period', ym)
    if doc.status == 'Locked':
        frappe.response['message'] = {'status': 'already_locked', 'name': ym}
    else:
        doc.status = 'Locked'
        doc.locked_by = u
        doc.locked_at = frappe.utils.now_datetime()
        doc.lock_reason = frappe.form_dict.get('reason') or 'Monthly HR lock'
        doc.flags.ignore_permissions = True
        doc.save(ignore_permissions=True)
        frappe.response['message'] = {'status': 'locked', 'name': ym, 'locked_by': u}
elif action == 'reopen':
    reason = (frappe.form_dict.get('reason') or '').strip()
    if not reason:
        frappe.throw('Reopen bat buoc co ly do (reason).')
    if not exists:
        frappe.throw('Ky chua ton tai.')
    doc = frappe.get_doc('EC HR Monthly Period', ym)
    doc.status = 'Open'
    doc.reopened_by = u
    doc.reopened_at = frappe.utils.now_datetime()
    doc.reopen_reason = reason
    doc.flags.ignore_permissions = True
    doc.save(ignore_permissions=True)
    frappe.response['message'] = {'status': 'reopened', 'name': ym, 'reopened_by': u}
else:
    frappe.throw('action khong hop le (create_or_open|lock|reopen)')

